// Trail kit tests (P03 DoD: pager.spec.js green). Plain Node (node --test), no browser or npm packages needed:
// the pure parts of trail.js (cursor, mock router, Pager window, idempotency engine, events) run as-is.
//   node --test test-ui/tests/pager.spec.js
// Covers MASTER_PLAN 4.5 (pagination contract, against the mock router the trail uses in Mock mode) and 4.4
// (the 50/25/24 client window), on the committed seed fixtures (test-ui/fixtures/seed, generated by seed/).
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const Trail = require('../trail.js');
const FX = path.join(__dirname, '..', 'fixtures', 'seed');
const fx = name => JSON.parse(fs.readFileSync(path.join(FX, name + '.json'), 'utf8')).data;
const seed = () => ({ personas: fx('personas'), expenses: fx('expenses'), categories: fx('categories'),
  merchants: fx('merchants'), catalogCards: fx('catalog-cards'), userCards: fx('user-cards') });

function fresh() {
  Trail._reset();
  Trail.setMode('mock');
  Trail.settings.latencyMs = [0, 0];
  return Trail.useSeed(seed());
}
const get = p => Trail.api('GET', p);
const ids = rows => rows.map(r => r.id);

async function walk(base, limit, first = limit) {
  const out = []; let cursor = null; let pages = 0; let r;
  do {
    const q = new URLSearchParams({ limit: String(pages === 0 ? first : limit) });
    if (cursor) q.set('cursor', cursor);
    r = await get(base + (base.includes('?') ? '&' : '?') + q);
    assert.equal(r.status, 200, JSON.stringify(r.data));
    out.push(...r.data.data); cursor = r.data.page.nextCursor; pages++;
  } while (r.data.page.hasMore);
  return { rows: out, pages, last: r.data.page };
}
const ordered = rows => rows.every((r, i) => i === 0 || rows[i - 1].occurredAt > r.occurredAt
  || (rows[i - 1].occurredAt === r.occurredAt && rows[i - 1].id > r.id));

// ------------------------------------------------------------------ fixtures
test('seed fixtures: two demo tenants with 500 live expenses at most, newest first', () => {
  const p = fx('personas');
  assert.deepEqual(p.map(x => x.key), ['asha', 'ravi', 'admin']);
  const e = fx('expenses');
  for (const who of p.filter(x => x.accountId)) {
    const mine = e.filter(x => x.accountId === who.accountId);
    assert.ok(mine.length > 480 && mine.length <= 500, `${who.key}: ${mine.length}`); // ~1% are soft-deleted
  }
  assert.equal(fx('catalog-cards').length, 40);
  assert.ok(fx('catalog-cards').every(c => c.name.startsWith('MOCK_')));
  assert.ok(fx('merchants').length >= 300);
});

// ------------------------------------------------------------------ MASTER_PLAN 4.5 contract (mock router)
test('4.5.1 first page with limit 50 returns 50 items and hasMore', async () => {
  fresh(); Trail.usePersona('asha');
  const r = await get('/api/v1/expenses?limit=50');
  assert.equal(r.status, 200);
  assert.equal(r.data.data.length, 50);
  assert.equal(r.data.page.hasMore, true);
  assert.equal(r.data.page.limit, 50);
  assert.match(r.data.page.nextCursor, /^[A-Za-z0-9_-]+\.[0-9a-f]{16}$/);
});

test('4.5.2 walking all pages yields every row exactly once, in order', async () => {
  const { expenses } = fresh(); Trail.usePersona('asha');
  const asha = Trail.persona.accountId;
  const expected = expenses.rows().filter(r => r.accountId === asha);
  const { rows, pages } = await walk('/api/v1/expenses', 25, 50);
  assert.equal(rows.length, expected.length);
  assert.equal(new Set(ids(rows)).size, rows.length);
  assert.ok(ordered(rows));
  assert.ok(rows.every(r => r.accountId === asha));
  assert.equal(pages, 1 + Math.ceil((expected.length - 50) / 25));
});

test('4.5.3 200 rows with an identical timestamp: no duplicates, no gaps', async () => {
  Trail._reset(); Trail.settings.latencyMs = [0, 0];
  const t = '2026-09-01T10:00:00.000Z';
  const rows = Array.from({ length: 200 }, () => ({ id: Trail.uuidv4(), accountId: 'A', occurredAt: t }))
    .concat(Array.from({ length: 30 }, (_, i) => ({ id: Trail.uuidv4(), accountId: 'A', occurredAt: `2026-09-0${1 + (i % 3)}T09:00:00.000Z` })));
  const coll = Trail.collection({ rows, filters: {} });
  const seen = []; let c = null; let r;
  do { r = coll.list({ limit: 7, cursor: c }, 'A'); seen.push(...r.data); c = r.page.nextCursor; } while (r.page.hasMore);
  assert.equal(seen.length, 230);
  assert.equal(new Set(ids(seen)).size, 230);
  assert.ok(ordered(seen));
});

test('4.5.4 rows inserted above the cursor mid-walk cause no duplicates later', async () => {
  fresh(); Trail.usePersona('ravi');
  const first = await get('/api/v1/expenses?limit=50');
  for (let i = 0; i < 5; i++) {
    const r = await Trail.api('POST', '/api/v1/expenses', { headers: { 'Idempotency-Key': Trail.uuidv4() },
      body: { amountPaise: 1000 + i, occurredAt: '2026-09-30T23:59:00Z', merchant: 'mid-walk insert' } });
    assert.equal(r.status, 201);
  }
  const rest = await walk('/api/v1/expenses?limit=25&cursor=' + encodeURIComponent(first.data.page.nextCursor), 25);
  const all = first.data.data.concat(rest.rows);
  assert.equal(new Set(ids(all)).size, all.length);
  assert.ok(!all.some(r => r.merchantDisplay === 'mid-walk insert'), 'new rows sort above the cursor');
});

test('4.5.5 the last page has hasMore=false and a null cursor', async () => {
  fresh(); Trail.usePersona('asha');
  const { last } = await walk('/api/v1/expenses', 100);
  assert.equal(last.hasMore, false);
  assert.equal(last.nextCursor, null);
});

test('4.5.6 tampered cursor → CURSOR_INVALID; other filters → CURSOR_FILTER_MISMATCH', async () => {
  fresh(); Trail.usePersona('asha');
  const r = await get('/api/v1/expenses?limit=10&category=food');
  assert.equal(r.status, 200);
  assert.ok(r.data.data.every(x => x.categoryPath === 'food' || x.categoryPath.startsWith('food.')));
  const c = r.data.page.nextCursor;
  const flip = c.slice(0, 5) + (c[5] === 'A' ? 'B' : 'A') + c.slice(6);
  for (const bad of [flip, c.slice(0, -1) + (c.endsWith('0') ? '1' : '0'), 'garbage', c.split('.')[0]]) {
    const t = await get('/api/v1/expenses?limit=10&category=food&cursor=' + encodeURIComponent(bad));
    assert.equal(t.status, 400); assert.equal(t.data.code, 'CURSOR_INVALID'); assert.ok(t.data.requestId);
  }
  const m = await get('/api/v1/expenses?limit=10&category=travel&cursor=' + encodeURIComponent(c));
  assert.equal(m.status, 400); assert.equal(m.data.code, 'CURSOR_FILTER_MISMATCH');
  const ok = await get('/api/v1/expenses?category=food&limit=10&cursor=' + encodeURIComponent(c));
  assert.equal(ok.status, 200, 'parameter order does not matter');
});

test('4.5.7 limit=101 and limit=0 → 400 LIMIT_INVALID', async () => {
  fresh(); Trail.usePersona('asha');
  for (const l of ['101', '0', '-1', 'x', '2.5']) {
    const r = await get('/api/v1/expenses?limit=' + l);
    assert.equal(r.status, 400, l); assert.equal(r.data.code, 'LIMIT_INVALID');
  }
  assert.equal((await get('/api/v1/expenses')).data.page.limit, 25, 'default 25');
});

test("4.5.8 tenant B's cursor used by tenant A still returns only A's rows (RLS)", async () => {
  fresh(); Trail.usePersona('ravi');
  const ravi = await get('/api/v1/expenses?limit=25');
  Trail.usePersona('asha');
  const asha = Trail.persona.accountId;
  const r = await get('/api/v1/expenses?limit=25&cursor=' + encodeURIComponent(ravi.data.page.nextCursor));
  assert.equal(r.status, 200);
  assert.ok(r.data.data.length > 0);
  assert.ok(r.data.data.every(x => x.accountId === asha));
  const other = ravi.data.data[0].id;
  assert.equal((await get('/api/v1/expenses/' + other)).status, 404, "another tenant's row is not found");
  Trail.usePersona(null);
  assert.equal((await get('/api/v1/expenses')).data.code, 'UNAUTHENTICATED');
  Trail.usePersona('admin');
  assert.equal((await get('/api/v1/expenses')).data.data.length, 0, 'an admin is not a ledger tenant');
});

// ------------------------------------------------------------------ MASTER_PLAN 4.4 window
function windowOver(fetchPage) {
  const calls = [];
  const p = Trail.pager({ fetchPage: async q => { calls.push(q.limit); return fetchPage(q); } });
  return { p, calls };
}

test('4.4 init fetches 50 and shows 25; item 24 shows 26–50 instantly and prefetches 51–75', async () => {
  fresh(); Trail.usePersona('asha');
  const { p, calls } = windowOver(async ({ limit, cursor }) =>
    (await get('/api/v1/expenses?limit=' + limit + (cursor ? '&cursor=' + encodeURIComponent(cursor) : ''))).data);
  await p.init();
  assert.deepEqual(calls, [50]);
  assert.equal(p.shown, 25); assert.equal(p.buffer.length, 50);
  await p.onItemVisible(23);
  assert.equal(calls.length, 1, 'no fetch before the trigger item');
  const visible = p.onItemVisible(24);
  assert.equal(p.shown, 50, 'shown grows before the network answers');
  assert.equal(p.state.inflight, true);
  p.onItemVisible(24); // a second trigger while in flight does not fetch twice
  await visible;
  assert.deepEqual(calls, [50, 25]);
  assert.equal(p.buffer.length, 75);
  assert.equal(p.state.inflight, false);
});

test('4.4 scrolling to the end shows every row once with 1 + ceil((n-50)/25) fetches', async () => {
  const { expenses } = fresh(); Trail.usePersona('asha');
  const n = expenses.rows().filter(r => r.accountId === Trail.persona.accountId).length;
  const { p, calls } = windowOver(async ({ limit, cursor }) =>
    (await get('/api/v1/expenses?limit=' + limit + (cursor ? '&cursor=' + encodeURIComponent(cursor) : ''))).data);
  await p.init();
  for (let i = 1; i <= n + 30 && (p.hasMore || i <= p.shown); i++) await p.onItemVisible(Math.min(i, p.shown));
  assert.equal(p.shown, n); assert.equal(p.buffer.length, n); assert.equal(p.hasMore, false);
  assert.equal(new Set(ids(p.buffer)).size, n);
  assert.ok(ordered(p.buffer));
  assert.equal(calls.length, 1 + Math.ceil((n - 50) / 25));
  assert.ok(calls.slice(1).every(l => l === 25));
});

test('4.4 running past the buffer waits on the in-flight page (skeleton), then continues', async () => {
  let release; const gate = new Promise(r => { release = r; });
  const pages = [Array.from({ length: 50 }, (_, i) => ({ id: 'a' + String(1000 - i) })), Array.from({ length: 25 }, (_, i) => ({ id: 'b' + i }))];
  let k = 0; const skel = [];
  const p = Trail.pager({ fetchPage: async () => { const d = pages[k++]; if (k === 2) await gate; return { data: d, page: { hasMore: k < 2, nextCursor: k < 2 ? 'c' : null } }; },
    onChange: s => { if (s.skeleton) skel.push(s.buffered); } });
  await p.init();
  p.onItemVisible(24);           // prefetch starts, blocked on the gate
  const late = p.onItemVisible(50); // the user is already at the end of the buffer
  await new Promise(r => setTimeout(r, 5));
  assert.deepEqual(skel, [50], 'skeleton shown while waiting');
  release(); await late;
  assert.equal(p.buffer.length, 75); assert.equal(p.shown, 75);
});

test('4.4 overlapping pages are de-duplicated by id', async () => {
  const pages = [[1, 2, 3].map(i => ({ id: 'x' + i })), [3, 4].map(i => ({ id: 'x' + i }))];
  let k = 0;
  const p = Trail.pager({ first: 3, page: 2, fetchPage: async () => { const d = pages[k++]; return { data: d, page: { hasMore: k < 2, nextCursor: k < 2 ? 'c' : null } }; } });
  await p.init(); await p.onItemVisible(2); await p.onItemVisible(3);
  assert.deepEqual(ids(p.buffer), ['x1', 'x2', 'x3', 'x4']);
  assert.equal(p.state.duplicatesDropped, 1);
});

test('4.4 reset during a fetch drops the stale page (tenant switch)', async () => {
  let release; const gate = new Promise(r => { release = r; });
  let k = 0;
  const p = Trail.pager({ fetchPage: async () => { k++; if (k === 1) await gate; return { data: [{ id: 'gen' + k }], page: { hasMore: false, nextCursor: null } }; } });
  const first = p.init();
  const second = p.init(); // e.g. the user switched tenant
  await second; release(); await first;
  assert.deepEqual(ids(p.buffer), ['gen2']);
});

// ------------------------------------------------------------------ idempotency (MASTER_PLAN 5.5, mock engine)
test('5.5 same key twice → one row and a replay; different body → 422; no key → 400', async () => {
  const { expenses } = fresh(); Trail.usePersona('asha');
  const before = expenses.rows().length;
  const key = Trail.uuidv4();
  const body = { amountPaise: 12345, occurredAt: '2026-09-15T08:00:00Z', merchant: 'Idem test' };
  const r1 = await Trail.api('POST', '/api/v1/expenses', { body, headers: { 'Idempotency-Key': key } });
  const r2 = await Trail.api('POST', '/api/v1/expenses', { body, headers: { 'Idempotency-Key': key } });
  assert.equal(r1.status, 201); assert.equal(r2.status, 201);
  assert.equal(r1.headers['idempotent-replayed'], undefined);
  assert.equal(r2.headers['idempotent-replayed'], 'true');
  assert.deepEqual(r2.data, r1.data);
  assert.equal(expenses.rows().length, before + 1);
  assert.equal(Trail.events.recent().filter(e => e.aggregateId === r1.data.id).length, 1, 'one outbox event');
  const r3 = await Trail.api('POST', '/api/v1/expenses', { body: { ...body, amountPaise: 1 }, headers: { 'Idempotency-Key': key } });
  assert.equal(r3.status, 422); assert.equal(r3.data.code, 'IDEMPOTENCY_KEY_REUSED');
  const r4 = await Trail.api('POST', '/api/v1/expenses', { body });
  assert.equal(r4.status, 400); assert.equal(r4.data.code, 'IDEMPOTENCY_KEY_REQUIRED');
  const invalid = await Trail.api('POST', '/api/v1/expenses', { body: { amountPaise: 0 }, headers: { 'Idempotency-Key': Trail.uuidv4() } });
  assert.equal(invalid.status, 400); assert.equal(invalid.data.code, 'VALIDATION_FAILED');
  assert.deepEqual(invalid.data.errors.map(e => e.field).sort(), ['amountPaise', 'occurredAt']);
});

test('5.5 20 parallel requests with one key create exactly one row; keys are tenant-scoped', async () => {
  const { expenses } = fresh(); Trail.usePersona('ravi');
  Trail.settings.latencyMs = [1, 3];
  const before = expenses.rows().length;
  const key = Trail.uuidv4();
  const body = { amountPaise: 777, occurredAt: '2026-09-20T08:00:00Z' };
  const rs = await Promise.all(Array.from({ length: 20 }, () =>
    Trail.api('POST', '/api/v1/expenses', { body, headers: { 'Idempotency-Key': key } })));
  assert.ok(rs.every(r => r.status === 201));
  assert.equal(new Set(rs.map(r => r.data.id)).size, 1);
  assert.equal(rs.filter(r => r.headers['idempotent-replayed'] === 'true').length, 19);
  assert.equal(expenses.rows().length, before + 1);
  Trail.usePersona('asha');
  const other = await Trail.api('POST', '/api/v1/expenses', { body, headers: { 'Idempotency-Key': key } });
  assert.equal(other.status, 201); assert.equal(other.headers['idempotent-replayed'], undefined);
  assert.notEqual(other.data.id, rs[0].data.id);
});

// ------------------------------------------------------------------ other mock routes
test('catalog is global (no tenant) and paged by the same rules; filters bind to the cursor', async () => {
  fresh();
  const all = await walk('/api/v1/catalog/cards', 15);
  assert.equal(all.rows.length, 40);
  const visa = await get('/api/v1/catalog/cards?limit=5&network=visa');
  assert.ok(visa.data.data.every(c => c.network === 'visa'));
  const bad = await get('/api/v1/catalog/cards?limit=5&network=rupay&cursor=' + encodeURIComponent(visa.data.page.nextCursor));
  assert.equal(bad.data.code, 'CURSOR_FILTER_MISMATCH');
  assert.equal((await get('/api/v1/catalog/cards?nope=1')).data.code, 'VALIDATION_FAILED');
});

test('mock login, /me and user cards follow the persona', async () => {
  fresh(); Trail.usePersona('asha');
  const me = await get('/api/v1/me');
  assert.equal(me.data.email, 'asha@demo.in');
  const cards = await get('/api/v1/cards?limit=10');
  assert.equal(cards.data.data.length, 3);
  const login = await Trail.login('ravi', 'whatever');
  assert.equal(login.status, 200);
  assert.equal(Trail.persona.key, 'ravi');
  assert.equal((await get('/api/v1/cards')).data.data.length, 2);
  assert.equal((await get('/api/v1/nothing')).status, 501);
});
